package app.aventurine.jetmapdemo.utils

import androidx.compose.ui.unit.IntOffset
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.withContext
import java.util.PriorityQueue
import kotlin.coroutines.coroutineContext
import kotlin.math.abs
import kotlin.math.min

/**
 * Grid A* over a [CostMap].
 *
 * Fixes over the previous version:
 *  - works on a primitive grid instead of `Bitmap.get` per neighbour,
 *  - bounds are checked explicitly, not through exceptions,
 *  - terrain friction and the heuristic use the same scale, so the heuristic actually guides the
 *    search instead of degenerating into Dijkstra,
 *  - diagonal moves may not cut corners,
 *  - the result is "string pulled" (line of sight simplification), which is what makes the drawn
 *    route look like a map route instead of grid stairs.
 */
class AStarPathFinder {

    suspend fun findPath(
        start: IntOffset,
        end: IntOffset,
        costMap: CostMap,
        maxIterations: Int = DEFAULT_MAX_ITERATIONS
    ): List<IntOffset> = withContext(Dispatchers.Default) {
        if (!costMap.isWalkable(start.x, start.y) || !costMap.isWalkable(end.x, end.y)) {
            return@withContext emptyList()
        }

        val width = costMap.width
        val startIndex = start.y * width + start.x
        val endIndex = end.y * width + end.x

        if (startIndex == endIndex) {
            return@withContext listOf(start)
        }

        val gScore = HashMap<Int, Int>()
        val parents = HashMap<Int, Int>()
        val closed = HashSet<Int>()

        // f in the high 32 bits, cell index in the low ones: ordering for free, no allocation
        // of a comparator object per node.
        val open = PriorityQueue<Long>()

        gScore[startIndex] = 0
        open.add(encode(f = heuristic(start.x, start.y, end.x, end.y), index = startIndex))

        var iterations = 0

        while (open.isNotEmpty()) {
            if (iterations++ % YIELD_INTERVAL == 0) {
                coroutineContext.ensureActive()
            }

            if (iterations > maxIterations) {
                return@withContext emptyList()
            }

            val currentIndex = decodeIndex(open.poll()!!)
            if (currentIndex == endIndex) {
                return@withContext simplify(
                    path = reconstruct(parents = parents, endIndex = endIndex, width = width),
                    costMap = costMap
                )
            }

            if (!closed.add(currentIndex)) {
                continue
            }

            val currentX = currentIndex % width
            val currentY = currentIndex / width
            val currentG = gScore[currentIndex] ?: continue

            for (direction in 0 until NEIGHBOUR_COUNT) {
                val neighbourX = currentX + NEIGHBOUR_DX[direction]
                val neighbourY = currentY + NEIGHBOUR_DY[direction]

                if (!costMap.isWalkable(neighbourX, neighbourY)) {
                    continue
                }

                val isDiagonal = direction >= 4
                if (isDiagonal && !canCutCorner(costMap, currentX, currentY, neighbourX, neighbourY)) {
                    continue
                }

                val neighbourIndex = neighbourY * width + neighbourX
                if (neighbourIndex in closed) {
                    continue
                }

                val stepCost = (if (isDiagonal) DIAGONAL_COST else STRAIGHT_COST) +
                        costMap.friction(neighbourX, neighbourY)

                val tentativeG = currentG + stepCost
                if (tentativeG >= (gScore[neighbourIndex] ?: Int.MAX_VALUE)) {
                    continue
                }

                gScore[neighbourIndex] = tentativeG
                parents[neighbourIndex] = currentIndex
                open.add(
                    encode(
                        f = tentativeG + heuristic(neighbourX, neighbourY, end.x, end.y),
                        index = neighbourIndex
                    )
                )
            }
        }

        emptyList()
    }

    /** Diagonal moves are only allowed when both adjacent orthogonal cells are free. */
    private fun canCutCorner(
        costMap: CostMap,
        fromX: Int,
        fromY: Int,
        toX: Int,
        toY: Int
    ): Boolean = costMap.isWalkable(toX, fromY) && costMap.isWalkable(fromX, toY)

    private fun heuristic(x: Int, y: Int, endX: Int, endY: Int): Int {
        val dx = abs(x - endX)
        val dy = abs(y - endY)
        // Octile distance, admissible because the step cost is never below STRAIGHT_COST.
        return STRAIGHT_COST * (dx + dy) + (DIAGONAL_COST - 2 * STRAIGHT_COST) * min(dx, dy)
    }

    private fun reconstruct(
        parents: Map<Int, Int>,
        endIndex: Int,
        width: Int
    ): List<IntOffset> {
        val path = ArrayList<IntOffset>()
        var index: Int? = endIndex

        while (index != null) {
            path.add(IntOffset(x = index % width, y = index / width))
            index = parents[index]
        }

        path.reverse()
        return path
    }

    /**
     * Removes every point that can be skipped without leaving the walkable area. Turns the raw
     * grid staircase into a handful of long straight segments.
     */
    private fun simplify(path: List<IntOffset>, costMap: CostMap): List<IntOffset> {
        if (path.size < 3) {
            return path
        }

        val result = ArrayList<IntOffset>()
        result.add(path.first())

        var anchor = 0
        var probe = 1

        while (probe < path.lastIndex) {
            if (!hasLineOfSight(path[anchor], path[probe + 1], costMap)) {
                result.add(path[probe])
                anchor = probe
            }
            probe++
        }

        result.add(path.last())
        return result
    }

    private fun hasLineOfSight(from: IntOffset, to: IntOffset, costMap: CostMap): Boolean {
        var x = from.x
        var y = from.y
        val dx = abs(to.x - x)
        val dy = abs(to.y - y)
        val stepX = if (to.x > x) 1 else -1
        val stepY = if (to.y > y) 1 else -1
        var error = dx - dy

        while (true) {
            if (!costMap.isWalkable(x, y)) {
                return false
            }

            if (x == to.x && y == to.y) {
                return true
            }

            val doubledError = error shl 1
            if (doubledError > -dy) {
                error -= dy
                x += stepX
            }
            if (doubledError < dx) {
                error += dx
                y += stepY
            }
        }
    }

    private fun encode(f: Int, index: Int): Long =
        (f.toLong() shl 32) or (index.toLong() and 0xFFFFFFFFL)

    private fun decodeIndex(value: Long): Int = (value and 0xFFFFFFFFL).toInt()

    private companion object {
        const val STRAIGHT_COST = 10
        const val DIAGONAL_COST = 14
        const val NEIGHBOUR_COUNT = 8
        const val YIELD_INTERVAL = 512
        const val DEFAULT_MAX_ITERATIONS = 2_000_000

        val NEIGHBOUR_DX = intArrayOf(0, 0, -1, 1, -1, 1, -1, 1)
        val NEIGHBOUR_DY = intArrayOf(-1, 1, 0, 0, -1, -1, 1, 1)
    }
}

package app.aventurine.jetmapdemo.utils

import androidx.compose.ui.unit.IntOffset
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import java.util.BitSet
import kotlin.coroutines.coroutineContext
import kotlin.math.abs
import kotlin.math.min

/**
 * Grid A* over a [CostMap].
 *
 * Memory notes (the boxed version reliably hit `OutOfMemoryError` on large floors):
 *  - `HashMap<Int, Int>` for g-scores/parents and `HashSet<Int>` for the closed set boxed every
 *    visited cell; on a 5 million cell floor that is hundreds of MB of `Integer` objects. They are
 *    replaced by flat primitive arrays allocated once and reused between runs.
 *  - the parent link is stored as a direction byte (0..7) instead of a full cell index, which cuts
 *    that buffer from 20 MB to 5 MB.
 *  - the open list is a primitive long heap instead of `PriorityQueue<Long>`.
 */
class AStarPathFinder {

    /** Reusable buffers; A* runs are serialised so a single set is enough. */
    private class Scratch(val width: Int, val height: Int) {
        val gScore = IntArray(width * height)
        val parentDirection = ByteArray(width * height)
        val closed = BitSet(width * height)
        val open = LongMinHeap()

        fun reset() {
            gScore.fill(Int.MAX_VALUE)
            parentDirection.fill(NO_PARENT)
            closed.clear()
            open.clear()
        }
    }

    private val scratchMutex = Mutex()
    private var scratch: Scratch? = null

    suspend fun findPath(
        start: IntOffset,
        end: IntOffset,
        costMap: CostMap,
        maxIterations: Int = DEFAULT_MAX_ITERATIONS
    ): List<IntOffset> = scratchMutex.withLock {
        withContext(Dispatchers.Default) {
            search(start = start, end = end, costMap = costMap, maxIterations = maxIterations)
        }
    }

    /** Frees the scratch buffers, e.g. once routing is finished. */
    suspend fun release() = scratchMutex.withLock {
        scratch = null
    }

    private suspend fun search(
        start: IntOffset,
        end: IntOffset,
        costMap: CostMap,
        maxIterations: Int
    ): List<IntOffset> {
        if (!costMap.isWalkable(start.x, start.y) || !costMap.isWalkable(end.x, end.y)) {
            return emptyList()
        }

        val width = costMap.width
        val startIndex = start.y * width + start.x
        val endIndex = end.y * width + end.x

        if (startIndex == endIndex) {
            return listOf(start)
        }

        val buffers = scratchOf(costMap = costMap)
        buffers.reset()

        val gScore = buffers.gScore
        val parentDirection = buffers.parentDirection
        val closed = buffers.closed
        val open = buffers.open

        gScore[startIndex] = 0
        open.push(encode(f = heuristic(start.x, start.y, end.x, end.y), index = startIndex))

        var iterations = 0

        while (!open.isEmpty) {
            if (iterations++ % YIELD_INTERVAL == 0) {
                coroutineContext.ensureActive()
            }

            if (iterations > maxIterations) {
                return emptyList()
            }

            val currentIndex = decodeIndex(open.pop())
            if (currentIndex == endIndex) {
                return simplify(
                    path = reconstruct(
                        parentDirection = parentDirection,
                        startIndex = startIndex,
                        endIndex = endIndex,
                        width = width
                    ),
                    costMap = costMap
                )
            }

            if (closed.get(currentIndex)) {
                continue
            }
            closed.set(currentIndex)

            val currentX = currentIndex % width
            val currentY = currentIndex / width
            val currentG = gScore[currentIndex]

            for (direction in 0 until NEIGHBOUR_COUNT) {
                val neighbourX = currentX + NEIGHBOUR_DX[direction]
                val neighbourY = currentY + NEIGHBOUR_DY[direction]

                if (!costMap.isWalkable(neighbourX, neighbourY)) {
                    continue
                }

                val isDiagonal = direction >= DIAGONAL_START
                if (isDiagonal && !canCutCorner(costMap, currentX, currentY, neighbourX, neighbourY)) {
                    continue
                }

                val neighbourIndex = neighbourY * width + neighbourX
                if (closed.get(neighbourIndex)) {
                    continue
                }

                val stepCost = (if (isDiagonal) DIAGONAL_COST else STRAIGHT_COST) +
                        costMap.friction(neighbourX, neighbourY)

                val tentativeG = currentG + stepCost
                if (tentativeG >= gScore[neighbourIndex]) {
                    continue
                }

                gScore[neighbourIndex] = tentativeG
                parentDirection[neighbourIndex] = direction.toByte()
                open.push(
                    encode(
                        f = tentativeG + heuristic(neighbourX, neighbourY, end.x, end.y),
                        index = neighbourIndex
                    )
                )
            }
        }

        return emptyList()
    }

    private fun scratchOf(costMap: CostMap): Scratch {
        val current = scratch
        if (current != null && current.width == costMap.width && current.height == costMap.height) {
            return current
        }

        // Drop the old buffers first so two generations are never alive at the same time.
        scratch = null
        return Scratch(width = costMap.width, height = costMap.height).also { scratch = it }
    }

    /** Diagonal moves are only allowed when both adjacent orthogonal cells are free. */
    private fun canCutCorner(
        costMap: CostMap,
        fromX: Int,
        fromY: Int,
        toX: Int,
        toY: Int
    ): Boolean = costMap.isWalkable(toX, fromY) && costMap.isWalkable(fromX, toY)

    private fun heuristic(x: Int, y: Int, endX: Int, endY: Int): Int {
        val dx = abs(x - endX)
        val dy = abs(y - endY)
        // Octile distance, admissible because the step cost is never below STRAIGHT_COST.
        return STRAIGHT_COST * (dx + dy) + (DIAGONAL_COST - 2 * STRAIGHT_COST) * min(dx, dy)
    }

    private fun reconstruct(
        parents: Map<Int, Int>,
        endIndex: Int,
        width: Int
    ): List<IntOffset> {
        val path = ArrayList<IntOffset>()
        var index: Int? = endIndex

        while (index != null) {
            path.add(IntOffset(x = index % width, y = index / width))
            index = parents[index]
        }

        path.reverse()
        return path
    }

    /**
     * Removes every point that can be skipped without leaving the walkable area. Turns the raw
     * grid staircase into a handful of long straight segments.
     */
    private fun simplify(path: List<IntOffset>, costMap: CostMap): List<IntOffset> {
        if (path.size < 3) {
            return path
        }

        val result = ArrayList<IntOffset>()
        result.add(path.first())

        var anchor = 0
        var probe = 1

        while (probe < path.lastIndex) {
            if (!hasLineOfSight(path[anchor], path[probe + 1], costMap)) {
                result.add(path[probe])
                anchor = probe
            }
            probe++
        }

        result.add(path.last())
        return result
    }

    private fun hasLineOfSight(from: IntOffset, to: IntOffset, costMap: CostMap): Boolean {
        var x = from.x
        var y = from.y
        val dx = abs(to.x - x)
        val dy = abs(to.y - y)
        val stepX = if (to.x > x) 1 else -1
        val stepY = if (to.y > y) 1 else -1
        var error = dx - dy

        while (true) {
            if (!costMap.isWalkable(x, y)) {
                return false
            }

            if (x == to.x && y == to.y) {
                return true
            }

            val doubledError = error shl 1
            if (doubledError > -dy) {
                error -= dy
                x += stepX
            }
            if (doubledError < dx) {
                error += dx
                y += stepY
            }
        }
    }

    private fun encode(f: Int, index: Int): Long =
        (f.toLong() shl 32) or (index.toLong() and 0xFFFFFFFFL)

    private fun decodeIndex(value: Long): Int = (value and 0xFFFFFFFFL).toInt()

    private companion object {
        const val STRAIGHT_COST = 10
        const val DIAGONAL_COST = 14
        const val NEIGHBOUR_COUNT = 8
        const val YIELD_INTERVAL = 512
        const val DEFAULT_MAX_ITERATIONS = 2_000_000

        val NEIGHBOUR_DX = intArrayOf(0, 0, -1, 1, -1, 1, -1, 1)
        val NEIGHBOUR_DY = intArrayOf(-1, 1, 0, 0, -1, -1, 1, 1)
    }
}

package app.aventurine.jetmap.controller.gesture
import app.aventurine.jetmap.controller.marker.models.MarkerDescriptor import kotlinx.coroutines.flow.StateFlow
interface GestureApi { val focusedMarkerFlow: StateFlow<MarkerDescriptor?> fun changeFocusedMarker(focusedMarker: MarkerDescriptor?) }

package app.aventurine.jetmap.controller.gesture
import app.aventurine.jetmap.controller.gesture.models.MapTapResult import app.aventurine.jetmap.controller.marker.models.MarkerDescriptor import kotlinx.coroutines.flow.SharedFlow import kotlinx.coroutines.flow.StateFlow
interface GestureApi { val focusedMarkerFlow: StateFlow<MarkerDescriptor?>
/** * Every tap on the map, already resolved against the marker provider. * Emitted for empty space too, which is what makes "pick any point as route origin" possible. */ val tapResultFlow: SharedFlow<MapTapResult>
fun changeFocusedMarker(focusedMarker: MarkerDescriptor?) }

package app.aventurine.jetmap.controller.gesture

import androidx.compose.ui.geometry.Offset
import app.aventurine.jetmap.controller.gesture.models.TapEvent
import app.aventurine.jetmap.controller.marker.models.MarkerDescriptor
import app.aventurine.jetmap.controller.motion.MotionState
import app.aventurine.jetmap.provider.MarkerProvider
import app.aventurine.jetmap.utils.screenToMap
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

internal class GestureController(
    private val markerProvider: MarkerProvider
) : GestureApi {

    /**
     * Buffered so a tap emitted before the collector attaches is not silently dropped.
     */
    private val _tapFlow: MutableSharedFlow<TapEvent> = MutableSharedFlow(
        replay = 0,
        extraBufferCapacity = 1
    )

    internal val tapFlow: SharedFlow<TapEvent> = _tapFlow.asSharedFlow()

    private val _focusedMarkerFlow: MutableStateFlow<MarkerDescriptor?> =
        MutableStateFlow(value = null)
    override val focusedMarkerFlow: StateFlow<MarkerDescriptor?> = _focusedMarkerFlow.asStateFlow()

    internal fun onTap(
        tapArea: Float,
        offset: Offset,
        motionState: MotionState,
        level: Int
    ) {
        _tapFlow.tryEmit(
            value = TapEvent(
                mapOffset = motionState.screenToMap(screenOffset = offset),
                level = level,
                tapArea = tapArea
            )
        )
    }

    internal suspend fun onMarkerFocusChanged(tapEvent: TapEvent) {
        val markerDescriptor = try {
            markerProvider.getMarker(
                x = tapEvent.mapOffset.x.toInt(),
                y = tapEvent.mapOffset.y.toInt(),
                z = tapEvent.level,
                tapArea = tapEvent.tapArea
            )
        } catch (e: CancellationException) {
            throw e
        } catch (_: Exception) {
            null
        }

        changeFocusedMarker(focusedMarker = markerDescriptor)
    }

    override fun changeFocusedMarker(focusedMarker: MarkerDescriptor?) {
        _focusedMarkerFlow.update { focusedMarker }
    }
}

package app.aventurine.jetmap.controller.gesture

import androidx.compose.ui.geometry.Offset
import app.aventurine.jetmap.controller.gesture.models.MapTapResult
import app.aventurine.jetmap.controller.gesture.models.TapEvent
import app.aventurine.jetmap.controller.marker.models.MarkerDescriptor
import app.aventurine.jetmap.controller.motion.MotionState
import app.aventurine.jetmap.provider.MarkerProvider
import app.aventurine.jetmap.utils.screenToMap
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

internal class GestureController(
    private val markerProvider: MarkerProvider
) : GestureApi {

    /**
     * Buffered so a tap emitted before the collector attaches is not silently dropped.
     */
    private val _tapFlow: MutableSharedFlow<TapEvent> = MutableSharedFlow(
        replay = 0,
        extraBufferCapacity = 1
    )

    internal val tapFlow: SharedFlow<TapEvent> = _tapFlow.asSharedFlow()

    private val _tapResultFlow: MutableSharedFlow<MapTapResult> = MutableSharedFlow(
        replay = 0,
        extraBufferCapacity = 1
    )

    override val tapResultFlow: SharedFlow<MapTapResult> = _tapResultFlow.asSharedFlow()

    private val _focusedMarkerFlow: MutableStateFlow<MarkerDescriptor?> =
        MutableStateFlow(value = null)
    override val focusedMarkerFlow: StateFlow<MarkerDescriptor?> = _focusedMarkerFlow.asStateFlow()

    internal fun onTap(
        tapArea: Float,
        offset: Offset,
        motionState: MotionState,
        level: Int
    ) {
        _tapFlow.tryEmit(
            value = TapEvent(
                mapOffset = motionState.screenToMap(screenOffset = offset),
                level = level,
                tapArea = tapArea
            )
        )
    }

    internal suspend fun onMarkerFocusChanged(tapEvent: TapEvent) {
        val markerDescriptor = try {
            markerProvider.getMarker(
                x = tapEvent.mapOffset.x.toInt(),
                y = tapEvent.mapOffset.y.toInt(),
                z = tapEvent.level,
                tapArea = tapEvent.tapArea
            )
        } catch (e: CancellationException) {
            throw e
        } catch (_: Exception) {
            null
        }

        changeFocusedMarker(focusedMarker = markerDescriptor)

        _tapResultFlow.emit(
            value = MapTapResult(
                mapOffset = tapEvent.mapOffset,
                level = tapEvent.level,
                marker = markerDescriptor
            )
        )
    }

    override fun changeFocusedMarker(focusedMarker: MarkerDescriptor?) {
        _focusedMarkerFlow.update { focusedMarker }
    }
}

package app.aventurine.jetmap.ui

import androidx.compose.ui.unit.IntSize

data class JetMapConfig(
    val tileSize: Int,
    val mapSize: IntSize,
    val initialLevel: Int = 0,
    val minZoom: Float = 0.1f,
    val maxZoom: Float = 10f,
    /** Extra ring of tiles fetched around the visible area to hide loading while panning. */
    val tilePrefetchMargin: Int = 1,
    /** Max number of decoded tiles kept in memory (LRU). */
    // 256 tiles of 256x256 ARGB_8888 are ~64 MB, which alone eats a quarter of a default heap.
    val tileCacheSize: Int = 128,
    /** Max number of tiles decoded in parallel. */
    val tileParallelism: Int = 4,
    /** Enables pan inertia after a fling gesture. */
    val flingEnabled: Boolean = true,
    /** Zoom multiplier applied on double tap. */
    val doubleTapZoomFactor: Float = 2f,
    /** Keeps the camera inside the map bounds. */
    val clampToBounds: Boolean = true,
    /** Average travel speed in map units per second, used for ETA. */
    val navigationSpeedUnitsPerSecond: Float = 60f,
    /** Zoom used by the turn-by-turn camera. */
    val navigationZoom: Float = 4f,
    /** Distance from the polyline (map units) above which the user is considered off route. */
    val offRouteThreshold: Float = 12f,
    /** Distance to the destination (map units) at which arrival is triggered. */
    val arrivalThreshold: Float = 4f,
) {
    val xTileCount: Int = mapSize.width / tileSize
    val yTileCount: Int = mapSize.height / tileSize

    data class Coordinates(
        val startX: Int,
        val startY: Int,
        val endX: Int,
        val endY: Int
    )
}

